def solve(nums, k):
    def partition(arr, low, high):
        pivot = arr[high]
        i = low
        j = high - 1
        while i <= j:
            if arr[i] < pivot:
                i += 1
            elif arr[j] > pivot:
                j -= 1
            else:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1
        arr[i], arr[high] = arr[high], arr[i]
        return i

    def quickselect(arr, k):
        low = 0
        high = len(arr) - 1
        while low <= high:
            pivot_index = partition(arr, low, high)
            if pivot_index == k - 1:
                return arr[pivot_index]
            elif pivot_index < k - 1:
                low = pivot_index + 1
            else:
                high = pivot_index - 1

    nums_copy = nums[:]
    quickselect(nums_copy, k)
    return nums_copy[k - 1]

