def sort_array_ascending(arr):
    # This function sorts an array in ascending order using a simple bubble sort algorithm
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

