def solve(nums):
    def find_dup(nums):
            # Use Floyd's cycle detection algorithm
            # This method finds the duplicate by detecting a cycle in the sequence
            # of numbers, which is guaranteed to exist
            slow = fast = nums[0]
            while True:
                slow = nums[slow]
                fast = nums[nums[fast]]
                if slow == fast:
                    break
            # Now find the entrance to the cycle
            slow = nums[0]
            while slow != fast:
                slow = nums[slow]
                fast = nums[fast]
            return slow
    return find_dup(nums)

