def find_important_path(nodes, edges):
    # Build the graph
    graph = {node: [] for node in nodes}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Find a path from the first node to the last node using BFS
    start = nodes[0]
    end = nodes[-1]

    visited = set()
    queue = [(start, [start])]

    while queue:
        current, path = queue.pop(0)
        if current == end:
            return path  # Found the path
        if current in visited:
            continue
        visited.add(current)
        for neighbor in graph[current]:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))

    return None  # No path found

