def solve(n, edges):
    if n == 0:
        return -1
    if n == 1:
        return 0

    from collections import defaultdict, deque

    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for u, v, w in edges:
        graph[u].append((v, w))
        in_degree[v] += 1

    queue = deque()
    for node in range(n):
        if in_degree.get(node, 0) == 0:
            queue.append(node)

    topo_order = []
    while queue:
        current = queue.popleft()
        topo_order.append(current)
        for neighbor, _ in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topo_order) != n:
        return -1

    dist = [float('inf')] * n
    dist[0] = 0

    for u in topo_order:
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w

    return dist[n-1] if dist[n-1] != float('inf') else -1

