def solve(n, edges):
    def is_reachable(start, end, graph):
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node == end:
                return True
            if node in visited:
                continue
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    stack.append(neighbor)
        return False

    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append(v)

    if n == 0:
        return 0

    for i in range(n):
        for j in range(n):
            if i != j:
                if not is_reachable(i, j, graph):
                    return -1

    return 0

